#!/usr/bin/env python3
"""Writes returns_250.csv: 250 synthetic daily returns, oldest first.

Deterministic (a fixed-seed linear congruential generator, no library
randomness), so the fixture can be regenerated byte for byte. The series
is a small drift, a slow cycle and noise, in the range a liquid equity
index moves in a day. It is synthetic: no real prices.

Usage: python3 make_returns_250.py > returns_250.csv
"""
import math

state = 20261127


def uniform():
    """Next value in [0, 1) from the Numerical Recipes LCG."""
    global state
    state = (1664525 * state + 1013904223) % 2**32
    return state / 2**32


def normal():
    """A standard normal draw (Box-Muller, cosine branch)."""
    u1, u2 = uniform(), uniform()
    return math.sqrt(-2.0 * math.log(1.0 - u1)) * math.cos(2.0 * math.pi * u2)


print("daily_return")
for day in range(250):
    r = 0.0003 + 0.002 * math.sin(2.0 * math.pi * day / 63.0) + 0.011 * normal()
    print(f"{r:.8f}")
